{
  "groups": [
    {
      "group_id": "high_rate_shock_vulnerable",
      "rule": "rate_type == 'fixed' and origination_year >= 2021 and mortgage_rate_pct > 4.0",
      "rationale": "Borrowers who entered the market recently with fixed rates that have reset or are approaching high market levels are most likely to seek alternatives."
    },
    {
      "group_id": "floating_rate_high_exposure",
      "rule": "rate_type == 'variable' and mortgage_rate_pct > 5.0 and origination_year <= 2020",
      "rationale": "Borrowers with older variable rate mortgages face compounding interest rate pressure and are actively shopping to stabilize payments."
    },
    {
      "group_id": "constrained_lower_income",
      "rule": "household_income_cad < 75000 and n_children >= 2",
      "rationale": "Large households with limited income are susceptible to liquidity crunches and demonstrate higher sensitivity to mortgage payment changes."
    },
    {
      "group_id": "uninsured_credit_seekers",
      "rule": "insured_flag == False and credit_score_band == '600_659'",
      "rationale": "Uninsured borrowers with moderate credit scores often seek better terms to offset the lack of insurance protection and manage debt costs."
    },
    {
      "group_id": "early_tenure_stability_seekers",
      "rule": "td_tenure_months <= 24 and rate_type == 'fixed'",
      "rationale": "Newer clients are still in the early phase of their relationship with the lender and are most likely to switch if they feel they overpaid at origination."
    },
    {
      "group_id": "high_balance_affluent_optimizers",
      "rule": "mortgage_balance_cad > 480000 and has_investments == True",
      "rationale": "Affluent clients with large mortgages and investment portfolios are strategic, price-sensitive shoppers who prioritize yield management."
    }
  ]
}
